csui.define('csui/controls/form/fields/alpaca/alpcsuifield',['module', 'csui/lib/underscore', 'csui/lib/jquery',
	'csui/lib/backbone', 'csui/lib/marionette', 'csui/lib/alpaca/js/alpaca.lite'],
	function (module, _, $, Backbone, Marionette, Alpaca) {

		var Field = Alpaca.Fields.TextField.extend({
			setup: function () {
				this.base();
				this.csuiValue = this.data;
				this.setValue(this.data);
			},

			postRender: function (callback) {
				this.base(callback);
				this.showField();
				this.field.parent().addClass("csui-field-" + this.getFieldType());
			},

			setValueAndValidate: function (value, validate) {
				this.setValue(value);
				this.csuiValue = value;
				return true;
			},

			_showField: function (_fieldView) {
				var id = this.id;
				var id4Label, id4Description = this.options ? this.options.descriptionId
					: '', labelElement = $(this.field[0]).find('label');
				if (labelElement && labelElement.length === 1) {
					id4Label = labelElement.attr('for') + "Label";
					labelElement.attr('id', id4Label);
				}

				this.fieldView = new _fieldView({
					model: new Backbone.Model({
						data: this.data,
						options: this.options,
						schema: this.schema,
						id: id
					}),
					id: _.uniqueId(id),
					alpacaField: this,
					labelId: id4Label,
					descriptionId: id4Description,
					value: this.data,
					readonly: true,
					dataId: this.name,
					path: this.path,
					alpaca: {
						data: this.data,
						options: this.options,
						schema: this.schema
					}
				});

				var $field = $('<div>').addClass('alpaca-control');
				this.getControlEl().replaceWith($field);
				this.region = new Marionette.Region({ el: $field });
				this.region.show(this.fieldView);
				return;
			},
			getValue: function () {
				var bRet = this.csuiValue;
				return bRet;
			},

			focus: function () {
				this.fieldView.setFocus();
			},

			destroy: function () {
				this.base();
				if (this.region) {
					this.region.destroy();
				}
			}

		});

		return Field;
	});